import{_ as r,C as c,o as a,c as E,a4 as d,E as o}from"./chunks/framework.DAD9IEko.js";const O=JSON.parse('{"title":"C 语言仿真验证 — 总索引","description":"","frontmatter":{"date":"2026-06-04T00:00:00.000Z","section":"电机控制","chapter":"simulation","chapterTitle":"仿真与调试","chapterOrder":10,"category":"仿真与调试","source":"motor","visibility":"public","title":"C 语言仿真验证 — 总索引","tags":["motor-control"],"status":"learning","summary":"**版本：** v1.0 **日期：** 2026-05 **适用对象：** 电机控制学习者、嵌入式开发者","navGroup":"实践与验证","navGroupOrder":40},"headers":[],"relativePath":"content/motor/simulation/SIM-00-C-Simulation-Overview.md","filePath":"content/motor/simulation/SIM-00-C-Simulation-Overview.md","lastUpdated":1783233977000}'),_={name:"content/motor/simulation/SIM-00-C-Simulation-Overview.md"};function i(l,t,h,n,s,C){const e=c("MermaidDiagram");return a(),E("div",null,[t[0]||(t[0]=d('<h1 id="c-语言仿真验证-—-总索引" tabindex="-1">C 语言仿真验证 — 总索引 <a class="header-anchor" href="#c-语言仿真验证-—-总索引" aria-label="Permalink to &quot;C 语言仿真验证 — 总索引&quot;">​</a></h1><p><strong>版本：</strong> v1.0 <strong>日期：</strong> 2026-05 <strong>适用对象：</strong> 电机控制学习者、嵌入式开发者</p><blockquote><p>本索引将知识库理论模块与 emachinery C 语言仿真工程的运行模式建立对应关系，支持&quot;按需查阅&quot;——学完某节理论后，在此查找对应的仿真验证方案。</p></blockquote><div class="kb-table-scroll"><table><thead><tr><th>快速入口</th><th>说明</th></tr></thead><tbody><tr><td><a href="./SIM-01-C-Simulation-QuickStart.html">SIM-01 快速上手指南</a></td><td>第一次使用仿真？从环境搭建到跑通第一个例子</td></tr><tr><td><a href="./SIM-02-C-Simulation-Code-Map.html">SIM-02 代码概念映射</a></td><td>想深入理解 C 代码实现？理论概念→代码位置的精确映射</td></tr><tr><td><a href="./SIM-03-C-Simulation-Plotting.html">SIM-03 仿真绘图系统</a></td><td>想自定义绘图？.dat 文件→matplotlib 完整管线</td></tr><tr><td><a href="./SIM-04-emachinery-Complete-Usage-Tutorial.html">SIM-04 完整使用教程</a></td><td>从零开始的系统教程：架构、操作、模式、插件、扩展、进阶</td></tr></tbody></table></div><hr><h2 id="启动-emachinery-仿真" tabindex="-1">启动 emachinery 仿真 <a class="header-anchor" href="#启动-emachinery-仿真" aria-label="Permalink to &quot;启动 emachinery 仿真&quot;">​</a></h2><p>emachinery 是一个独立的 Streamlit 应用，需要<strong>先在 Windows 中启动</strong>才能使用：</p><p><strong>第一步：启动仿真服务器</strong> 双击 <code>E:\\new_things\\emy-start.bat</code>（约 10 秒启动，会弹出命令行窗口和一个浏览器标签页）</p><p><strong>第二步：在浏览器中操作仿真</strong> 启动后默认打开 <code>http://localhost:8501/</code>，在 Streamlit 界面中选择电机、选择仿真模式、调参数、点击「Save to C and compile」运行仿真</p><p><strong>备用方式：仅编译运行 C 代码（无需浏览器）</strong> 双击 <code>E:\\new_things\\emy-c-build.bat</code> → 编译成功后手动运行 <code>main.exe</code> → 输出 <code>.dat</code> 数据文件</p><blockquote><p>首次使用请确保已安装 TDM-GCC-64 和 Python 虚拟环境（<code>E:\\new_things\\emy-env</code>）。详见 <a href="./SIM-01-C-Simulation-QuickStart.html#1-环境准备">SIM-01 环境准备</a>。</p></blockquote><hr><h2 id="_1-仿真工程简介" tabindex="-1">1. 仿真工程简介 <a class="header-anchor" href="#_1-仿真工程简介" aria-label="Permalink to &quot;1. 仿真工程简介&quot;">​</a></h2><p>emachinery 是一个 <strong>Python + C 混合</strong> 的电机控制数值仿真框架。</p><div class="kb-table-scroll"><table><thead><tr><th>层</th><th>语言</th><th>职责</th></tr></thead><tbody><tr><td><strong>GUI 层</strong></td><td>Python (Streamlit)</td><td>参数配置、电机选择、模式切换、结果可视化</td></tr><tr><td><strong>仿真引擎</strong></td><td>C</td><td>电机状态方程的 RK4 数值积分、控制算法执行、观测器计算</td></tr><tr><td><strong>桥梁层</strong></td><td>Python (<code>super_config.py</code>)</td><td>YAML 配置 → C 头文件/源文件自动生成</td></tr><tr><td><strong>后处理层</strong></td><td>Python (<code>cplot.py</code>)</td><td>读取仿真输出 <code>.dat</code> 文件 → matplotlib 绘图</td></tr></tbody></table></div><p><strong>支持电机类型：</strong> PMSM（永磁同步电机）、IM（感应电机）</p><p><strong>涵盖仿真模式：</strong> 24 种（从 PWM 直接控制到 Nyquist 图绘制）</p><p><strong>与纯理论推导的不同：</strong></p><ul><li>可以看到真实的电流/转速/转矩波形</li><li>可以观察阶跃响应、参数失配影响</li><li>可以扫频获取实测 Bode 图和 Nyquist 图</li></ul><p><strong>与 DSP 实验代码的不同：</strong></p><ul><li>没有硬件限制，可以自由修改参数和算法</li><li>编译运行在 PC 端，秒级完成仿真</li><li>支持任意精度的浮点运算（<code>REAL</code> = <code>double</code>）</li></ul><hr><h2 id="_2-kb-模块-→-仿真模式对应表-核心部分" tabindex="-1">2. KB 模块 → 仿真模式对应表（核心部分） <a class="header-anchor" href="#_2-kb-模块-→-仿真模式对应表-核心部分" aria-label="Permalink to &quot;2. KB 模块 → 仿真模式对应表（核心部分）&quot;">​</a></h2><h3 id="主题-a-foc-基础与电流环" tabindex="-1">主题 A: FOC 基础与电流环 <a class="header-anchor" href="#主题-a-foc-基础与电流环" aria-label="Permalink to &quot;主题 A: FOC 基础与电流环&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>KB 模块</th><th>仿真验证内容</th><th>推荐 Mode</th><th>关键操作</th></tr></thead><tbody><tr><td><a href="./../algorithm/ALG-00-Current-Loop-Intuition.html">ALG-00 电流环直觉</a></td><td>观察 Kp/Ki 对电流阶跃响应的影响：增大 Kp 加快上升但可能超调，增大 Ki 消除静差但可能振荡</td><td><code>MODE_SELECT_FOC</code> (3)</td><td>在 sidebar 可调参数中改 <code>FOC.CLBW_HZ</code>（=Kp/L）和 <code>FOC.delta</code>（影响 Ki），设定 id=0, iq=额定值，观察 iD/iQ 子图的阶跃响应波形</td></tr><tr><td><a href="./../algorithm/ALG-01-FOC-Theory.html">ALG-01 FOC 理论</a></td><td>验证 Clarke→Park→PI→解耦→InvPark 完整变换链路：id/iq 是否正确解耦，角度变换是否正确</td><td><code>MODE_SELECT_FOC</code> (3)</td><td>设定非零 id 命令（如 id=0.5A, iq=0），观察 uAB 子图中 αβ 电压是否为旋转矢量；改变角度 theta_d，验证 dq 轴电流是否恒定</td></tr><tr><td><a href="./../algorithm/ALG-03-PI-Current-Regulator.html">ALG-03 PI 电流调节器</a></td><td>扫频验证电流环实际带宽：用正弦扫频激励测量电流环闭环频率响应，找到 -3dB 带宽点</td><td><code>MODE_SELECT_ID_SWEEPING_FREQ</code> (33) 或 <code>MODE_SELECT_IQ_SWEEPING_FREQ</code> (34)</td><td>启用扫频模式，电流环带宽理论值 = CLBW_HZ，实际 -3dB 点受采样延迟和离散化影响会略低</td></tr><tr><td><a href="./../algorithm/ALG-02-Current-Sampling-Timing.html">ALG-02 电流采样时序</a></td><td>理解采样周期 CL_TS 对电流环性能的影响：采样越快控制越好，但计算负担越大</td><td>任意 FOC 模式</td><td>改 <code>sim.CLTS</code>（如从 1e-4 改为 5e-4），观察电流环阶跃响应是否变差；同时注意 <code>NUMBER_OF_STEPS</code> 相应调整以保持总仿真时间</td></tr></tbody></table></div><hr><h3 id="主题-b-速度环与位置环" tabindex="-1">主题 B: 速度环与位置环 <a class="header-anchor" href="#主题-b-速度环与位置环" aria-label="Permalink to &quot;主题 B: 速度环与位置环&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>KB 模块</th><th>仿真验证内容</th><th>推荐 Mode</th><th>关键操作</th></tr></thead><tbody><tr><td><a href="./../algorithm/ALG-05-Sensored-FOC.html">ALG-05 有感 FOC</a></td><td>速度阶跃响应：给定阶跃转速指令，观察速度跟踪、iq 电流、转矩的时域响应</td><td><code>MODE_SELECT_VELOCITY_LOOP</code> (4)</td><td>修改 <code>pmsm_comm.c</code> 的 <code>_user_commands()</code> 函数中的转速指令序列（如 0→400rpm→-400rpm），添加负载阶跃（ACM.TLoad），观察 Speed/Torque 子图</td></tr><tr><td><a href="./../algorithm/ALG-12-Speed-Loop-Torque-Observer.html">ALG-12 速度环与转矩观测器</a></td><td>负载转矩在线估计：ESO 能否准确跟踪未知负载转矩</td><td><code>MODE_SELECT_VELOCITY_LOOP_USING_ESO_FOR_SPEED</code> (47)</td><td>在 <code>_user_commands()</code> 中施加未知负载阶跃，观察 <code>OFSR.esoaf.xTL</code> 是否跟踪真实负载 <code>ACM.TLoad</code></td></tr><tr><td><a href="./../control-theory/CT-04-PID-Control-Principles.html">CT-04 PID 控制原理</a></td><td>P/I/D 各环节对速度环响应的影响：纯P有静差，加I消除静差，加D抑制超调</td><td><code>MODE_SELECT_VELOCITY_LOOP</code> (4)</td><td>在 <code>init_CTRL()</code> 中分别将 <code>PID_Speed-&gt;Kp</code>/<code>Ki_CODE</code> 设为零，观察 Speed 子图的稳态误差和超调变化</td></tr><tr><td><a href="./../control-theory/CT-05-PID-Tuning-Implementation.html">CT-05 PID 整定与实现</a></td><td>TI InstaSPIN 整定公式验证：Kp=L<em>BW, Ki=Kp</em>R/L*Ts 的实际效果</td><td><code>MODE_SELECT_VELOCITY_LOOP</code> (4)</td><td>改 <code>FOC.delta</code>（速度/电流带宽比），delta 越大速度环越慢，观察 Speed 子图响应速度变化</td></tr><tr><td><a href="./../control-theory/CT-14-Cascaded-PID-Control.html">CT-14 级联 PID</a></td><td>电流环+速度环双环交互：速度环输出作为电流环给定</td><td><code>MODE_SELECT_VELOCITY_LOOP</code> (4)</td><td>改 <code>VL_EXE_PER_CL_EXE</code>（速度环降频比），如从 1 改为 10，观察速度环控制效果变差</td></tr><tr><td><a href="./../control-theory/CT-06-Feedforward-Control.html">CT-06 前馈控制</a></td><td>dq 轴解耦前馈的效果：抵消反电动势耦合项</td><td><code>MODE_SELECT_VELOCITY_LOOP</code> (4)</td><td>切换 YAML 中 <code>bool_apply_decoupling_voltages_to_current_regulation</code>，观察高速时 id/iq 耦合是否减少</td></tr></tbody></table></div><hr><h3 id="主题-c-无感控制与观测器" tabindex="-1">主题 C: 无感控制与观测器 <a class="header-anchor" href="#主题-c-无感控制与观测器" aria-label="Permalink to &quot;主题 C: 无感控制与观测器&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>KB 模块</th><th>仿真验证内容</th><th>推荐 Mode</th><th>关键操作</th></tr></thead><tbody><tr><td><a href="./../algorithm/ALG-06-Position-Speed-Observer.html">ALG-06 位置与速度观测器</a></td><td>角度跟踪观测器（ATO/PLL）：观测位置能否跟踪真实位置</td><td><code>MODE_SELECT_FOC_SENSORLESS</code> (31)</td><td>对比 <code>OBSV.theta_d</code>（观测角度）和 <code>ACM.theta_d</code>（真实角度），观察收敛过程和无感启动</td></tr><tr><td><a href="./../algorithm/ALG-07-Sensorless-Observers.html">ALG-07 无感观测器</a></td><td>多种观测器（反EMF/SMO/磁链/EKF）在低速和高速下的性能对比</td><td><code>MODE_SELECT_VELOCITY_LOOP_SENSORLESS</code> (41)</td><td>切换观测器类型，观察低速（&lt;100rpm）时的角度误差和高速反转时的跟踪性能</td></tr><tr><td><a href="./../control-theory/CT-11-Observer-Design.html">CT-11 观测器设计</a></td><td>观测器极点配置对收敛速度的影响：极点离原点越远收敛越快但对噪声越敏感</td><td><code>MODE_SELECT_Marino2005</code> (44)</td><td>改观测器增益参数，观察角度误差收敛曲线（初始角度偏差→收敛到零的时间）</td></tr><tr><td><a href="./../control-theory/CT-16-ADRC-Theory.html">CT-16 ADRC</a></td><td>ESO 扩张状态观测器：同时估计转速、位置、负载转矩</td><td><code>MODE_SELECT_VELOCITY_LOOP_USING_ESO_FOR_SPEED</code> (47)</td><td>改 <code>CAREFUL_ESOAF_OMEGA_OBSERVER</code>（观测器带宽），观察 OFSR.esoaf.xTL 对阶跃负载的估计</td></tr><tr><td><a href="./../control-theory/CT-17-LADRC-Linear-ADRC.html">CT-17 LADRC</a></td><td>线性 ADRC 验证：线性 ESO + 线性状态误差反馈控制律</td><td><code>MODE_SELECT_VELOCITY_LOOP_USING_ESO_FOR_SPEED</code> (47)</td><td>对比 ADRC 与 PI 速度环的抗扰动性能</td></tr></tbody></table></div><hr><h3 id="主题-d-参数辨识" tabindex="-1">主题 D: 参数辨识 <a class="header-anchor" href="#主题-d-参数辨识" aria-label="Permalink to &quot;主题 D: 参数辨识&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>KB 模块</th><th>仿真验证内容</th><th>推荐 Mode</th><th>关键操作</th></tr></thead><tbody><tr><td><a href="./../algorithm/ALG-13-Protection-Optimization.html">ALG-13 参数自整定</a></td><td>分步参数辨识全流程：电阻→电感→磁链→惯量，理解每步的物理原理</td><td><code>MODE_SELECT_COMMISSIONING</code> (9)</td><td>观察控制台输出：R 辨识（电流扫频+最小二乘拟合）、L 辨识（正弦激励+相干解调）、KE 辨识（反电动势法）、Js 辨识（Awaya1992 观测器）</td></tr><tr><td><a href="./../hardware/HW-01-Motor-Basics.html">HW-01 电机本体基础</a></td><td>不同电机参数（Ld/Lq、Rs、KE、Js）对控制性能的影响</td><td>任意 FOC 模式</td><td>在 Streamlit 中切换不同电机（SEW100W、SEW200W 等），观察相同 PI 参数下不同电机的响应差异</td></tr></tbody></table></div><hr><h3 id="主题-e-逆变器非线性与死区" tabindex="-1">主题 E: 逆变器非线性与死区 <a class="header-anchor" href="#主题-e-逆变器非线性与死区" aria-label="Permalink to &quot;主题 E: 逆变器非线性与死区&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>KB 模块</th><th>仿真验证内容</th><th>推荐 Mode</th><th>关键操作</th></tr></thead><tbody><tr><td><a href="./../algorithm/ALG-04-Deadtime-Compensation.html">ALG-04 死区补偿</a></td><td>逆变器非线性建模对比：理想/查表/Sigmoid拟合/Sul1996 模型</td><td><code>MODE_SELECT_INVERTER_NONLINEARITY_SENSORLESS</code> (49)</td><td>在 <code>ACMSim.h</code> 中改 <code>__INVERTER_NONLINEARITY</code> 宏（0=理想, 1=Sul1996, 2=Sigmoid, 3=LUT, 4=LUT_Indexed），观察电流波形畸变程度</td></tr><tr><td><a href="./../algorithm/ALG-10-Overmodulation.html">ALG-10 过调制</a></td><td>电压利用率极限：母线电压利用率接近 1.0 时进入过调制区</td><td>任意 FOC 模式</td><td>将转速指令设到接近额定转速，改 <code>LIMIT_DC_BUS_UTILIZATION</code> 从 0.96 到 1.0，观察 Vdc Util 子图和电流谐波</td></tr></tbody></table></div><hr><h3 id="主题-f-扫频与频域分析" tabindex="-1">主题 F: 扫频与频域分析 <a class="header-anchor" href="#主题-f-扫频与频域分析" aria-label="Permalink to &quot;主题 F: 扫频与频域分析&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>KB 模块</th><th>仿真验证内容</th><th>推荐 Mode</th><th>关键操作</th></tr></thead><tbody><tr><td><a href="./../control-theory/CT-03-Frequency-Response-Bode.html">CT-03 频域响应与 Bode 图</a></td><td>实测电流环/速度环频率响应，生成 Bode 图</td><td><code>MODE_SELECT_SWEEPING_FREQ_FOR_VELOCITY_AND_CURRENT</code> (46)</td><td>启用扫频，在 Streamlit 中切换到 <code>plugin_Sweeping</code> 插件查看自动生成的 Bode 图，找 -3dB 带宽和相位裕度</td></tr><tr><td><a href="./../control-theory/CT-07-Nyquist-Stability.html">CT-07 Nyquist 稳定判据</a></td><td>实测 Nyquist 图，验证系统稳定裕度</td><td><code>MODE_SELECT_NYQUIST_PLOTTING</code> (91)</td><td>观察 Nyquist 轨迹相对于 (-1, 0) 点的位置，判断闭环稳定性</td></tr></tbody></table></div><hr><h2 id="_3-仿真模式编号速查表" tabindex="-1">3. 仿真模式编号速查表 <a class="header-anchor" href="#_3-仿真模式编号速查表" aria-label="Permalink to &quot;3. 仿真模式编号速查表&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>Mode 值</th><th>宏名</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td><code>MODE_SELECT_PWM_DIRECT</code></td><td>PWM 直接控制：给定固定占空比</td></tr><tr><td>11</td><td><code>MODE_SELECT_VOLTAGE_OPEN_LOOP</code></td><td>电压开环控制：给定 αβ 轴电压旋转矢量</td></tr><tr><td>2</td><td><code>MODE_SELECT_WITHOUT_ENCODER_CURRENT_VECTOR_ROTATE</code></td><td>无编码器电流矢量旋转：开环电流控制</td></tr><tr><td>3</td><td><code>MODE_SELECT_FOC</code></td><td>磁场定向控制（有传感器）：Clarke→Park→PI→InvPark</td></tr><tr><td>31</td><td><code>MODE_SELECT_FOC_SENSORLESS</code></td><td>无传感器 FOC：观测器估计角度代替编码器</td></tr><tr><td>32</td><td><code>MODE_SELECT_INDIRECT_FOC</code></td><td>间接磁场定向控制（用于感应电机）</td></tr><tr><td>33</td><td><code>MODE_SELECT_ID_SWEEPING_FREQ</code></td><td>D 轴电流扫频：验证电流环 D 轴频率响应</td></tr><tr><td>34</td><td><code>MODE_SELECT_IQ_SWEEPING_FREQ</code></td><td>Q 轴电流扫频：验证电流环 Q 轴频率响应</td></tr><tr><td>4</td><td><code>MODE_SELECT_VELOCITY_LOOP</code></td><td>速度闭环控制（有感）：电流环+速度环级联</td></tr><tr><td>41</td><td><code>MODE_SELECT_VELOCITY_LOOP_SENSORLESS</code></td><td>无传感器速度闭环</td></tr><tr><td>42</td><td><code>MODE_SELECT_TESTING_SENSORLESS</code></td><td>无传感器算法测试模式</td></tr><tr><td>43</td><td><code>MODE_SELECT_VELOCITY_LOOP_WC_TUNER</code></td><td>速度环带宽整定（HitWall 分析）</td></tr><tr><td>44</td><td><code>MODE_SELECT_Marino2005</code></td><td>Marino 2005 年观测器实现</td></tr><tr><td>45</td><td><code>MODE_SELECT_VELOCITY_LOOP_HARNEFORS_1998</code></td><td>Harnefors 1998 反计算观测器</td></tr><tr><td>46</td><td><code>MODE_SELECT_SWEEPING_FREQ_FOR_VELOCITY_AND_CURRENT</code></td><td>速度/电流扫频：同时支持速度环和电流环扫频</td></tr><tr><td>47</td><td><code>MODE_SELECT_VELOCITY_LOOP_USING_ESO_FOR_SPEED</code></td><td>ESO 扩张状态观测器估计转速</td></tr><tr><td>48</td><td><code>MODE_SELECT_VARIABLE_PARAMETERS_VELOCITY_LOOP_SENSORLESS</code></td><td>变参数无传感器速度环</td></tr><tr><td>49</td><td><code>MODE_SELECT_INVERTER_NONLINEARITY_SENSORLESS</code></td><td>逆变器非线性补偿+无传感器控制</td></tr><tr><td>5</td><td><code>MODE_SELECT_POSITION_LOOP</code></td><td>位置闭环控制：位置环+速度环+电流环三级联</td></tr><tr><td>9</td><td><code>MODE_SELECT_COMMISSIONING</code></td><td>参数自整定全流程：R→L→KE→Js 分步辨识</td></tr><tr><td>91</td><td><code>MODE_SELECT_NYQUIST_PLOTTING</code></td><td>Nyquist 图绘制：扫频提取频率响应</td></tr><tr><td>98</td><td><code>MODE_SELECT_UDQ_GIVEN_TEST</code></td><td>给定 Udq 测试：直接设定 dq 轴电压</td></tr><tr><td>8</td><td><code>MODE_SELECT_GENERATOR</code></td><td>发电机模式</td></tr></tbody></table></div><hr><h2 id="_4-可观测信号速查表" tabindex="-1">4. 可观测信号速查表 <a class="header-anchor" href="#_4-可观测信号速查表" aria-label="Permalink to &quot;4. 可观测信号速查表&quot;">​</a></h2><h3 id="转速类" tabindex="-1">转速类 <a class="header-anchor" href="#转速类" aria-label="Permalink to &quot;转速类&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>变量表达式</th><th>物理含义</th><th>单位</th></tr></thead><tbody><tr><td><code>ACM.varOmega * MECH_RAD_PER_SEC_2_RPM</code></td><td>电机实际机械转速</td><td>rpm</td></tr><tr><td><code>(*CTRL).i-&gt;cmd_varOmega * MECH_RAD_PER_SEC_2_RPM</code></td><td>转速指令值</td><td>rpm</td></tr><tr><td><code>OFSR.esoaf.xOmg * ELEC_RAD_PER_SEC_2_RPM</code></td><td>ESO 估计转速</td><td>rpm</td></tr><tr><td><code>OBSV.varOmega * MECH_RAD_PER_SEC_2_RPM</code></td><td>观测器估计转速</td><td>rpm</td></tr></tbody></table></div><h3 id="电流类" tabindex="-1">电流类 <a class="header-anchor" href="#电流类" aria-label="Permalink to &quot;电流类&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>变量表达式</th><th>物理含义</th><th>单位</th></tr></thead><tbody><tr><td><code>ACM.iDQ[0]</code></td><td>电机实际 d 轴电流</td><td>A</td></tr><tr><td><code>ACM.iDQ[1]</code></td><td>电机实际 q 轴电流</td><td>A</td></tr><tr><td><code>(*CTRL).i-&gt;iDQ[0]</code></td><td>控制器测量 d 轴电流</td><td>A</td></tr><tr><td><code>(*CTRL).i-&gt;iDQ[1]</code></td><td>控制器测量 q 轴电流</td><td>A</td></tr><tr><td><code>(*CTRL).i-&gt;cmd_iDQ[0]</code></td><td>d 轴电流指令</td><td>A</td></tr><tr><td><code>(*CTRL).i-&gt;cmd_iDQ[1]</code></td><td>q 轴电流指令</td><td>A</td></tr><tr><td><code>ACM.iAB[0]</code></td><td>电机实际 α 轴电流</td><td>A</td></tr><tr><td><code>ACM.iAB[1]</code></td><td>电机实际 β 轴电流</td><td>A</td></tr></tbody></table></div><h3 id="转矩类" tabindex="-1">转矩类 <a class="header-anchor" href="#转矩类" aria-label="Permalink to &quot;转矩类&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>变量表达式</th><th>物理含义</th><th>单位</th></tr></thead><tbody><tr><td><code>ACM.Tem</code></td><td>电机电磁转矩</td><td>N·m</td></tr><tr><td><code>ACM.TLoad</code></td><td>负载转矩</td><td>N·m</td></tr><tr><td><code>OFSR.esoaf.xTL</code></td><td>ESO 估计负载转矩</td><td>N·m</td></tr></tbody></table></div><h3 id="电压类" tabindex="-1">电压类 <a class="header-anchor" href="#电压类" aria-label="Permalink to &quot;电压类&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>变量表达式</th><th>物理含义</th><th>单位</th></tr></thead><tbody><tr><td><code>ACM.uDQ[0]</code></td><td>电机实际 d 轴电压</td><td>V</td></tr><tr><td><code>ACM.uDQ[1]</code></td><td>电机实际 q 轴电压</td><td>V</td></tr><tr><td><code>ACM.uAB[0]</code></td><td>电机实际 α 轴电压</td><td>V</td></tr><tr><td><code>ACM.uAB[1]</code></td><td>电机实际 β 轴电压</td><td>V</td></tr><tr><td><code>(*CTRL).o-&gt;cmd_uDQ[0]</code></td><td>控制器输出 d 轴电压指令</td><td>V</td></tr><tr><td><code>(*CTRL).o-&gt;cmd_uDQ[1]</code></td><td>控制器输出 q 轴电压指令</td><td>V</td></tr><tr><td><code>(*CTRL).o-&gt;dc_bus_utilization_ratio</code></td><td>直流母线电压利用率</td><td>-</td></tr></tbody></table></div><h3 id="位置-角度类" tabindex="-1">位置/角度类 <a class="header-anchor" href="#位置-角度类" aria-label="Permalink to &quot;位置/角度类&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>变量表达式</th><th>物理含义</th><th>单位</th></tr></thead><tbody><tr><td><code>ACM.theta_d / M_PI * 180</code></td><td>电机实际电角度</td><td>°（度）</td></tr><tr><td><code>ACM.varTheta</code></td><td>电机实际机械角度</td><td>rad</td></tr><tr><td><code>(*CTRL).s-&gt;xRho / M_PI * 180</code></td><td>控制器使用的电角度</td><td>°（度）</td></tr><tr><td><code>OBSV.theta_d / M_PI * 180</code></td><td>观测器估计电角度</td><td>°（度）</td></tr></tbody></table></div><h3 id="磁链类" tabindex="-1">磁链类 <a class="header-anchor" href="#磁链类" aria-label="Permalink to &quot;磁链类&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>变量表达式</th><th>物理含义</th><th>单位</th></tr></thead><tbody><tr><td><code>ACM.KA</code></td><td>电机永磁磁链幅值</td><td>Wb</td></tr><tr><td><code>ACM.KL[2]</code></td><td>dq 轴电感矩阵元素</td><td>H</td></tr></tbody></table></div><hr><h2 id="_5-关键-c-文件速查表" tabindex="-1">5. 关键 C 文件速查表 <a class="header-anchor" href="#_5-关键-c-文件速查表" aria-label="Permalink to &quot;5. 关键 C 文件速查表&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>文件</th><th>核心职责</th><th>主要函数/结构体</th></tr></thead><tbody><tr><td><code>main.c</code></td><td>仿真主循环、RK4 四阶龙格库塔积分器、PMSM/IM 电机状态方程、逆变器模型</td><td><code>DYNAMICS_MACHINE()</code>（电机状态微分方程）、<code>inverter_model()</code>（逆变器非线性模型）、<code>main()</code>（仿真主循环）</td></tr><tr><td><code>pmsm_comm.c</code></td><td>PMSM 控制器核心实现</td><td><code>_onlyFOC()</code>（Clarke→Park→PI→解耦→InvPark）、<code>FOC_with_velocity_control()</code>（速度环+电流环级联）、<code>tustin_PI()</code>/<code>incremental_PI()</code>（两种 PI 实现）、<code>StepByStepCommissioning_NEW_WB()</code>（分步参数辨识）</td></tr><tr><td><code>pmsm_observer.c</code></td><td>PMSM 无感观测器集合</td><td>反EMF/SMO/磁链/EKF/MRAS 等多种观测器实现函数</td></tr><tr><td><code>main_switch.c</code></td><td>仿真模式调度器</td><td><code>main_switch()</code> 根据 <code>MODE_SELECT_*</code> 枚举值分发到 24 种不同的控制算法执行路径</td></tr><tr><td><code>im_controller.c</code></td><td>感应电机控制器</td><td>间接磁场定向控制（IFOC）实现</td></tr><tr><td><code>im_observer.c</code></td><td>感应电机观测器</td><td>感应电机专用观测器实现</td></tr><tr><td><code>shared_flux_estimator.c</code></td><td>共享磁链估算器模块</td><td>磁链幅值和角度在线估计</td></tr><tr><td><code>utility.c</code></td><td>工具函数</td><td><code>write_data_to_file()</code>（数据记录）、<code>sign()</code>（符号函数）、<code>_lpf()</code>（低通滤波器）、<code>angle_diff()</code>（角度差计算）</td></tr><tr><td><code>pi_math.h</code></td><td>PI 控制器宏定义</td><td><code>PI_MACRO</code>（TI 官方增量式 PI）、<code>PI_POS_MACRO</code>（位置环 PI）、<code>PI_MACRO</code>（老明 PI）</td></tr><tr><td><code>ACMSim.h</code></td><td>主头文件</td><td><code>struct MachineSimulated</code>（5 阶电机状态空间模型）、<code>struct ControllerForExperiment</code>（控制器结构体）、<code>MODE_SELECT_*</code> 枚举、跨文件 extern 声明</td></tr><tr><td><code>typedef.h</code></td><td>基础类型定义</td><td><code>REAL</code>（double）、<code>BOOL</code>（int）、<code>int32</code>、<code>Uint32</code>、<code>int16</code> 等</td></tr><tr><td><code>ACMConfig.h</code></td><td>仿真配置宏</td><td><code>PC_SIMULATION</code>、<code>WHO_IS_USER</code>、<code>ENABLE_COMMISSIONING</code>、电机类型选择</td></tr><tr><td><code>super_config.h</code></td><td><strong>自动生成</strong>：YAML 参数对应的 C 结构体类型定义</td><td><code>ST_D_SIM</code> 结构体（所有仿真参数的运行时结构）</td></tr><tr><td><code>super_config.c</code></td><td><strong>自动生成</strong>：结构体初始化函数</td><td><code>init_d_sim()</code> 将 YAML 配置值赋给 <code>ST_D_SIM</code> 结构体各成员</td></tr><tr><td><code>simuser_*.c/h</code></td><td>各用户的算法扩展</td><td>bezier: Bezier 曲线速度控制器；wb: 扫频/HitWall/Harnefors；cjh: 感应电机/Marino2005；yzz: RK4 观测器/逆变器补偿；cury, qian 等用户自定义算法</td></tr></tbody></table></div><hr><h2 id="_6-阅读建议" tabindex="-1">6. 阅读建议 <a class="header-anchor" href="#_6-阅读建议" aria-label="Permalink to &quot;6. 阅读建议&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>你的情况</th><th>建议路径</th></tr></thead><tbody><tr><td>第一次使用仿真？</td><td>→ <a href="./SIM-01-C-Simulation-QuickStart.html">SIM-01 快速上手指南</a></td></tr><tr><td>学完某节理论想验证？</td><td>→ 在本页 <strong>第 2 节对应表</strong> 查找 → 打开 Streamlit → 选择对应 Mode → 按&quot;关键操作&quot;列执行</td></tr><tr><td>想深入理解 C 代码实现？</td><td>→ <a href="./SIM-02-C-Simulation-Code-Map.html">SIM-02 代码概念映射</a></td></tr><tr><td>想看某个信号的波形？</td><td>→ 查本页 <strong>第 4 节可观测信号速查表</strong> 找变量名</td></tr></tbody></table></div><hr><h2 id="_7-附录-emachinery-仿真工程架构分析" tabindex="-1">7. 附录：emachinery 仿真工程架构分析 <a class="header-anchor" href="#_7-附录-emachinery-仿真工程架构分析" aria-label="Permalink to &quot;7. 附录：emachinery 仿真工程架构分析&quot;">​</a></h2><h3 id="_7-1-工程整体架构" tabindex="-1">7.1 工程整体架构 <a class="header-anchor" href="#_7-1-工程整体架构" aria-label="Permalink to &quot;7.1 工程整体架构&quot;">​</a></h3>',66)),o(e,{code:"flowchart%20TB%0A%20%20%20%20subgraph%20PythonUpper%5B%22Python%20%E5%B1%82%EF%BC%88%E4%B8%8A%E5%B1%82%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20ST_MAIN%5B%22st_main.py%3Cbr%2F%3EStreamlit%20GUI%22%5D%0A%20%20%20%20%20%20%20%20ST_INTERACT%5B%22st_interact.py%3Cbr%2F%3EUI%20%E4%BA%A4%E4%BA%92%E9%80%BB%E8%BE%91%22%5D%0A%20%20%20%20%20%20%20%20SUPER_CONFIG%5B%22super_config.py%3Cbr%2F%3EYAML%20%E2%86%92%20C%20%E4%BB%A3%E7%A0%81%E7%94%9F%E6%88%90%E5%99%A8%22%5D%0A%20%20%20%20%20%20%20%20CPLOT_UPPER%5B%22cplot.py%3Cbr%2F%3E.dat%20%E2%86%92%20matplotlib%20%E7%BB%98%E5%9B%BE%22%5D%0A%20%20%20%20%20%20%20%20USER_SCRIPT%5B%22user_script_main.py%3Cbr%2F%3E%E7%94%A8%E6%88%B7%E5%89%8D%E5%90%8E%E5%A4%84%E7%90%86%E5%85%A5%E5%8F%A3%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20CLayer%5B%22C%20%E5%B1%82%EF%BC%88%E4%BB%BF%E7%9C%9F%E5%BC%95%E6%93%8E%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20MAIN_C%5B%22main.c%3Cbr%2F%3ERK4%20%E7%A7%AF%E5%88%86%E5%99%A8%20%2B%20%E7%94%B5%E6%9C%BA%E7%8A%B6%E6%80%81%E6%96%B9%E7%A8%8B%22%5D%0A%20%20%20%20%20%20%20%20PMSM_COMM%5B%22pmsm_comm.c%3Cbr%2F%3EPMSM%20%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%0A%20%20%20%20%20%20%20%20PMSM_OBS%5B%22pmsm_observer.c%3Cbr%2F%3EPMSM%20%E8%A7%82%E6%B5%8B%E5%99%A8%22%5D%0A%20%20%20%20%20%20%20%20MAIN_SW%5B%22main_switch.c%3Cbr%2F%3E%E6%A8%A1%E5%BC%8F%E8%B0%83%E5%BA%A6%22%5D%0A%20%20%20%20%20%20%20%20IM_CTRL%5B%22im_controller.c%3Cbr%2F%3E%E6%84%9F%E5%BA%94%E7%94%B5%E6%9C%BA%E6%8E%A7%E5%88%B6%22%5D%0A%20%20%20%20%20%20%20%20IM_OBS%5B%22im_observer.c%3Cbr%2F%3E%E6%84%9F%E5%BA%94%E7%94%B5%E6%9C%BA%E8%A7%82%E6%B5%8B%22%5D%0A%20%20%20%20%20%20%20%20UTILITY%5B%22utility.c%3Cbr%2F%3E%E5%B7%A5%E5%85%B7%E5%87%BD%E6%95%B0%22%5D%0A%20%20%20%20%20%20%20%20SIMUSER%5B%22simuser_*.c%3Cbr%2F%3E%E7%94%A8%E6%88%B7%E8%87%AA%E5%AE%9A%E4%B9%89%E7%AE%97%E6%B3%95%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20PythonPost%5B%22Python%20%E5%B1%82%EF%BC%88%E5%90%8E%E5%A4%84%E7%90%86%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20CPLOT_POST%5B%22cplot.py%20%E8%AF%BB%E5%8F%96%20.dat%3Cbr%2F%3E%E2%86%92%20pandas%20DataFrame%3Cbr%2F%3E%E2%86%92%20matplotlib%20%E7%BB%98%E5%9B%BE%3Cbr%2F%3E%E2%86%92%20Streamlit%20UI%20%E6%98%BE%E7%A4%BA%3Cbr%2F%3E7%20%E4%B8%AA%E9%BB%98%E8%AE%A4%E5%AD%90%E5%9B%BE%20%2B%20%E7%94%A8%E6%88%B7%E8%87%AA%E5%AE%9A%E4%B9%89%E5%AD%90%E5%9B%BE%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20PythonUpper%20--%3E%7C%22super_config.py%20%E8%87%AA%E5%8A%A8%E7%94%9F%E6%88%90%3Cbr%2F%3Esuper_config.h%20%2F%20super_config.c%22%7C%20CLayer%0A%20%20%20%20CLayer%20--%3E%7C%22%E7%BC%96%E8%AF%91%20%E2%86%92%20main.exe%20%E8%BF%90%E8%A1%8C%3Cbr%2F%3E%E8%BE%93%E5%87%BA%20%E2%86%92%20stdout(%E6%97%A5%E5%BF%97)%20%2B%20..%2Fdat%2F*.dat(%E6%95%B0%E6%8D%AE)%22%7C%20PythonPost%0A"}),t[1]||(t[1]=d('<p><strong>数据桥梁：</strong> <code>super_config.py</code>（Python）自动生成 <code>super_config.h/c</code>（C），将 YAML 中配置的参数转换为 C 结构体的类型定义和初始化代码。<code>*.dat</code> 文件作为 C 仿真引擎到 Python 绘图层的输出接口。</p><h3 id="_7-2-python-层文件职责" tabindex="-1">7.2 Python 层文件职责 <a class="header-anchor" href="#_7-2-python-层文件职责" aria-label="Permalink to &quot;7.2 Python 层文件职责&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>st_main.py</code></td><td>Streamlit 主入口，调度 UI 和仿真流程</td></tr><tr><td><code>st_interact.py</code></td><td>UI 交互逻辑：电机选择、模式选择、参数编辑、编译触发</td></tr><tr><td><code>super_config.py</code></td><td>YAML 配置 → C 头文件/C 文件自动生成器</td></tr><tr><td><code>cplot.py</code></td><td>读取 C 仿真输出 <code>.dat</code> → matplotlib 绘图</td></tr><tr><td><code>user_script_main.py</code></td><td>用户自定义预处理（<code>user_pre_process</code>）/后处理（<code>user_cplot_post_process</code>）入口</td></tr><tr><td><code>user_config.yaml</code></td><td>默认仿真参数配置（CLTS, NUMBER_OF_STEPS, CLBW_HZ, delta...）</td></tr><tr><td><code>user_config_*.yaml</code></td><td>各用户的自定义配置（wb/cjh/yzz/cury/qian/gen/gzt/bezier/xm/zjl/wb2）</td></tr><tr><td><code>motor_library.json</code></td><td>电机参数数据库，包含 SEW100W/200W 等多种电机的额定参数和辨识参数</td></tr></tbody></table></div><h3 id="_7-3-c-层文件职责" tabindex="-1">7.3 C 层文件职责 <a class="header-anchor" href="#_7-3-c-层文件职责" aria-label="Permalink to &quot;7.3 C 层文件职责&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>main.c</code></td><td>仿真主循环、RK4 四阶龙格库塔积分器、PMSM/IM 电机状态方程（<code>DYNAMICS_MACHINE</code>）、逆变器模型（<code>inverter_model</code>）</td></tr><tr><td><code>pmsm_comm.c</code></td><td>PMSM 控制器：<code>_onlyFOC()</code>（Clarke→Park→PI→解耦→InvPark）、<code>FOC_with_velocity_control()</code>（速度环+电流环级联）、<code>tustin_PI()</code>/<code>incremental_PI()</code>（两种 PI 实现）、<code>StepByStepCommissioning_NEW_WB()</code>（分步参数辨识）</td></tr><tr><td><code>pmsm_observer.c</code></td><td>PMSM 无感观测器集合：反EMF/SMO/磁链/EKF/MRAS 等多种观测器</td></tr><tr><td><code>main_switch.c</code></td><td>仿真模式调度器：<code>main_switch()</code> 函数根据 <code>MODE_SELECT_*</code> 枚举值分发到 24 种不同的控制算法</td></tr><tr><td><code>im_controller.c</code></td><td>感应电机控制器（间接磁场定向控制 IFOC）</td></tr><tr><td><code>im_observer.c</code></td><td>感应电机观测器</td></tr><tr><td><code>shared_flux_estimator.c</code></td><td>共享磁链估算器模块</td></tr><tr><td><code>pi_math.h</code></td><td>TI 官方增量式 PI 宏（<code>PI_MACRO</code>）、位置环 PI 宏（<code>PI_POS_MACRO</code>）、老明 PI（<code>PI_MACRO</code>）</td></tr><tr><td><code>ACMSim.h</code></td><td>主头文件：<code>struct MachineSimulated</code>（5 阶电机状态空间模型）、<code>struct ControllerForExperiment</code>（控制器结构体）、<code>MODE_SELECT_*</code> 枚举、跨文件 extern 声明</td></tr><tr><td><code>typedef.h</code></td><td>基础类型定义：<code>REAL</code>（double）、<code>BOOL</code>（int）、<code>int32</code>、<code>Uint32</code>、<code>int16</code> 等</td></tr><tr><td><code>ACMConfig.h</code></td><td>仿真配置宏：<code>PC_SIMULATION</code>、<code>WHO_IS_USER</code>、<code>ENABLE_COMMISSIONING</code>、电机类型选择</td></tr><tr><td><code>super_config.h/c</code></td><td><strong>自动生成</strong>：<code>SuperConfig</code> 类解析 YAML 参数生成 C 结构体类型定义和 <code>init_d_sim()</code> 初始化函数</td></tr><tr><td><code>simuser_*.c/h</code></td><td>各用户的算法扩展（bezier: Bezier 曲线速度控制器, wb: 扫频/HitWall/Harnefors, cjh: 感应电机/Marino2005, yzz: RK4 观测器/逆变器补偿, cury, qian）</td></tr><tr><td><code>utility.c</code></td><td>工具函数：<code>write_data_to_file()</code>（数据记录）、<code>sign()</code>、<code>_lpf()</code>（低通滤波器）、<code>angle_diff()</code>（角度差）</td></tr><tr><td><code>makefile</code></td><td>GNU Make 编译规则</td></tr></tbody></table></div><h3 id="_7-4-数据流完整路径" tabindex="-1">7.4 数据流完整路径 <a class="header-anchor" href="#_7-4-数据流完整路径" aria-label="Permalink to &quot;7.4 数据流完整路径&quot;">​</a></h3>',6)),o(e,{code:"flowchart%20TD%0A%20%20%20%20A%5B%22user_config.yaml%3Cbr%2F%3E(%E5%8F%82%E6%95%B0%E9%85%8D%E7%BD%AE)%22%5D%20--%3E%20B%5B%22super_config.py%3Cbr%2F%3E(SuperConfig%20%E7%B1%BB%E8%A7%A3%E6%9E%90%20YAML%20%E2%86%92%20%E7%94%9F%E6%88%90%20C%20%E4%BB%A3%E7%A0%81)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22super_config.h%3Cbr%2F%3E(ST_D_SIM%20%E7%BB%93%E6%9E%84%E4%BD%93%E7%B1%BB%E5%9E%8B%E5%AE%9A%E4%B9%89)%22%5D%0A%20%20%20%20B%20--%3E%20D%5B%22super_config.c%3Cbr%2F%3E(init_d_sim()%20%E5%88%9D%E5%A7%8B%E5%8C%96%E5%87%BD%E6%95%B0)%22%5D%0A%20%20%20%20C%20--%3E%20E%5B%22gmake%20%E7%BC%96%E8%AF%91%3Cbr%2F%3Emain.c%20%2B%20pmsm_comm.c%20%2B%20pmsm_observer.c%20%2B%20...%22%5D%0A%20%20%20%20D%20--%3E%20E%0A%20%20%20%20E%20--%3E%20F%5B%22main.exe%20%E8%BF%90%E8%A1%8C%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22stdout%3Cbr%2F%3E(%E4%BB%BF%E7%9C%9F%E5%AE%9E%E6%97%B6%E6%97%A5%E5%BF%97%EF%BC%8C%E5%A6%82%20_%3D%25d%20%E8%BF%9B%E5%BA%A6)%22%5D%0A%20%20%20%20F%20--%3E%20H%5B%22..%2Fdat%2F%E7%94%B5%E6%9C%BA%E5%90%8D.dat%3Cbr%2F%3E(%E4%BB%BF%E7%9C%9F%E6%95%B0%E6%8D%AE%E6%96%87%E4%BB%B6%EF%BC%8C%E9%80%97%E5%8F%B7%E5%88%86%E9%9A%94)%22%5D%0A%20%20%20%20H%20--%3E%20I%5B%22cplot.py%20%E8%AF%BB%E5%8F%96%20.dat%3Cbr%2F%3E%E2%86%92%20pandas%20DataFrame%20%E2%86%92%20matplotlib%20%E7%BB%98%E5%9B%BE%22%5D%0A%20%20%20%20I%20--%3E%20J%5B%22Streamlit%20UI%20%E6%98%BE%E7%A4%BA%3Cbr%2F%3E7%20%E4%B8%AA%E9%BB%98%E8%AE%A4%E5%AD%90%E5%9B%BE%20%2B%20%E7%94%A8%E6%88%B7%E8%87%AA%E5%AE%9A%E4%B9%89%E5%AD%90%E5%9B%BE%22%5D%0A"}),t[2]||(t[2]=d('<h3 id="_7-5-仿真与实验的代码复用机制" tabindex="-1">7.5 仿真与实验的代码复用机制 <a class="header-anchor" href="#_7-5-仿真与实验的代码复用机制" aria-label="Permalink to &quot;7.5 仿真与实验的代码复用机制&quot;">​</a></h3><p>emachinery 框架的核心设计理念之一是 <strong>仿真代码与实验代码共享同一套 C 源码</strong>，通过条件编译实现环境适配：</p><ul><li>同一套 C 代码通过 <code>PC_SIMULATION</code> 宏区分仿真/实验环境</li><li><code>#if PC_SIMULATION</code> 块为仿真专用代码（如 <code>_user_time_varying_parameters()</code> 动态修改电机参数）</li><li><code>super_config.h/c</code> 由 Python 自动生成；在实验中由用户手动维护</li><li>仿真模式下 <code>__INVERTER_NONLINEARITY</code> 默认为 0（理想逆变器）</li><li>实验中 <code>#pragma DATA_SECTION</code> 指令指定 DSP 内存段，仿真中忽略</li></ul><p>这意味着：<strong>你在仿真中验证通过的 PI 参数和控制算法，可以直接迁移到 DSP 实验代码中</strong>，只需修改 <code>ACMConfig.h</code> 中的 <code>PC_SIMULATION</code> 宏即可切换编译目标。</p><h3 id="_7-6-用户代码扩展机制" tabindex="-1">7.6 用户代码扩展机制 <a class="header-anchor" href="#_7-6-用户代码扩展机制" aria-label="Permalink to &quot;7.6 用户代码扩展机制&quot;">​</a></h3><p>emachinery 支持多用户并行开发，每个用户可以创建独立的算法扩展和参数配置：</p><ul><li>每个用户可创建 <code>simuser_*.c/h</code> 存放自定义算法（通过 <code>WHO_IS_USER</code> 宏条件编译启用）</li><li><code>user_config_*.yaml</code> 存放自定义参数（通过 Streamlit 侧栏的&quot;可调参数&quot;面板加载）</li><li><code>user_script_main.py</code> 中 <code>user_pre_process(d_sim, user_config)</code> 实现仿真前参数定制，<code>user_cplot_post_process(d_sim, user_plot_config, post_run)</code> 实现自定义信号和子图</li><li><code>WHO_IS_USER</code> 宏值定义在 <code>ACMConfig.h</code> 中（如 USER_WB=101976, USER_CJH=2023231051 等）</li></ul><h3 id="_7-7-插件系统" tabindex="-1">7.7 插件系统 <a class="header-anchor" href="#_7-7-插件系统" aria-label="Permalink to &quot;7.7 插件系统&quot;">​</a></h3><p><code>_plugins/</code> 目录下的独立 Python 模块，通过 <code>st_main_plugin()</code> 动态加载：</p><div class="kb-table-scroll"><table><thead><tr><th>插件名</th><th>功能</th></tr></thead><tbody><tr><td><code>plugin_Sweeping</code></td><td>扫频分析 Bode 图自动生成</td></tr><tr><td><code>plugin_MOO</code></td><td>多目标优化（如带宽 vs 稳定裕度权衡）</td></tr><tr><td><code>plugin_Performance_calc</code></td><td>性能计算 / 带宽计算 / 上升时间等指标</td></tr><tr><td><code>plugin_Lissajous</code></td><td>李沙育图绘制（αβ 轴电流/电压轨迹）</td></tr><tr><td><code>plugin_arbitrarily_plot_2d</code></td><td>任意 2D 信号图绘制</td></tr><tr><td><code>plugin_example</code></td><td>插件开发示例</td></tr></tbody></table></div><p>插件不修改主流程，在主界面选择插件模式即可使用。</p><h3 id="_7-8-仿真模式完整列表-24-种" tabindex="-1">7.8 仿真模式完整列表（24 种） <a class="header-anchor" href="#_7-8-仿真模式完整列表-24-种" aria-label="Permalink to &quot;7.8 仿真模式完整列表（24 种）&quot;">​</a></h3><div class="kb-table-scroll"><table><thead><tr><th>Mode 值</th><th>宏名</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td><code>MODE_SELECT_PWM_DIRECT</code></td><td>PWM 直接控制：给定固定占空比</td></tr><tr><td>11</td><td><code>MODE_SELECT_VOLTAGE_OPEN_LOOP</code></td><td>电压开环控制：给定 αβ 轴电压旋转矢量</td></tr><tr><td>2</td><td><code>MODE_SELECT_WITHOUT_ENCODER_CURRENT_VECTOR_ROTATE</code></td><td>无编码器电流矢量旋转：开环电流控制</td></tr><tr><td>3</td><td><code>MODE_SELECT_FOC</code></td><td>磁场定向控制（有传感器）：Clarke→Park→PI→InvPark</td></tr><tr><td>31</td><td><code>MODE_SELECT_FOC_SENSORLESS</code></td><td>无传感器 FOC：观测器估计角度代替编码器</td></tr><tr><td>32</td><td><code>MODE_SELECT_INDIRECT_FOC</code></td><td>间接磁场定向控制（用于感应电机）</td></tr><tr><td>33</td><td><code>MODE_SELECT_ID_SWEEPING_FREQ</code></td><td>D 轴电流扫频：验证电流环 D 轴频率响应</td></tr><tr><td>34</td><td><code>MODE_SELECT_IQ_SWEEPING_FREQ</code></td><td>Q 轴电流扫频：验证电流环 Q 轴频率响应</td></tr><tr><td>4</td><td><code>MODE_SELECT_VELOCITY_LOOP</code></td><td>速度闭环控制（有感）：电流环+速度环级联</td></tr><tr><td>41</td><td><code>MODE_SELECT_VELOCITY_LOOP_SENSORLESS</code></td><td>无传感器速度闭环</td></tr><tr><td>42</td><td><code>MODE_SELECT_TESTING_SENSORLESS</code></td><td>无传感器算法测试模式</td></tr><tr><td>43</td><td><code>MODE_SELECT_VELOCITY_LOOP_WC_TUNER</code></td><td>速度环带宽整定（HitWall 分析）</td></tr><tr><td>44</td><td><code>MODE_SELECT_Marino2005</code></td><td>Marino 2005 年观测器实现</td></tr><tr><td>45</td><td><code>MODE_SELECT_VELOCITY_LOOP_HARNEFORS_1998</code></td><td>Harnefors 1998 反计算观测器</td></tr><tr><td>46</td><td><code>MODE_SELECT_SWEEPING_FREQ_FOR_VELOCITY_AND_CURRENT</code></td><td>速度/电流扫频：同时支持速度环和电流环扫频</td></tr><tr><td>47</td><td><code>MODE_SELECT_VELOCITY_LOOP_USING_ESO_FOR_SPEED</code></td><td>ESO 扩张状态观测器估计转速</td></tr><tr><td>48</td><td><code>MODE_SELECT_VARIABLE_PARAMETERS_VELOCITY_LOOP_SENSORLESS</code></td><td>变参数无传感器速度环</td></tr><tr><td>49</td><td><code>MODE_SELECT_INVERTER_NONLINEARITY_SENSORLESS</code></td><td>逆变器非线性补偿+无传感器控制</td></tr><tr><td>5</td><td><code>MODE_SELECT_POSITION_LOOP</code></td><td>位置闭环控制：位置环+速度环+电流环三级联</td></tr><tr><td>9</td><td><code>MODE_SELECT_COMMISSIONING</code></td><td>参数自整定全流程：R→L→KE→Js 分步辨识</td></tr><tr><td>91</td><td><code>MODE_SELECT_NYQUIST_PLOTTING</code></td><td>Nyquist 图绘制：扫频提取频率响应</td></tr><tr><td>98</td><td><code>MODE_SELECT_UDQ_GIVEN_TEST</code></td><td>给定 Udq 测试：直接设定 dq 轴电压</td></tr><tr><td>8</td><td><code>MODE_SELECT_GENERATOR</code></td><td>发电机模式</td></tr></tbody></table></div><h3 id="_7-9-关键注意事项" tabindex="-1">7.9 关键注意事项 <a class="header-anchor" href="#_7-9-关键注意事项" aria-label="Permalink to &quot;7.9 关键注意事项&quot;">​</a></h3><ol><li><p><strong>修改 <code>super_config.h/c</code> 无效</strong>：这两个文件由 Python 自动生成，下次编译会被覆盖。所有参数修改应通过 <code>user_config.yaml</code> 或 Streamlit UI 进行。</p></li><li><p><strong>仿真和实验共用 <code>pmsm_comm.c</code> 和 <code>main_switch.c</code></strong>：修改时注意 <code>#if PC_SIMULATION</code> 条件编译，确保你的修改不会破坏实验代码路径。</p></li><li><p><strong>首次运行如果遇到 gmake 报错 &quot;CreateProcess failed&quot;</strong>：重启电脑，或按顺序安装 MinGW + CCS 的 gmake，确保 PATH 环境变量中 gmake 可被正常找到。</p></li><li><p><strong>YAML 编码问题</strong>：如果 Streamlit 启动报 <code>UnicodeDecodeError</code>，确保 <code>user_config.yaml</code> 保存为 UTF-8 编码（<strong>不带 BOM</strong>）。Windows 记事本默认保存的 UTF-8 with BOM 会导致 YAML 解析失败。</p></li><li><p><strong><code>.dat</code> 文件路径</strong>：C 仿真程序运行时，输出的 <code>.dat</code> 文件位于 <code>../dat/</code> 目录（相对于 C 可执行文件所在目录），确保该目录存在且有写入权限。</p></li><li><p><strong>电机参数准确性</strong>：仿真中使用的电机参数来自 <code>motor_library.json</code>，辨识实验中如果辨识结果与真实值偏差较大，检查 YAML 中的激励信号幅值是否合适（太小信噪比低，太大可能饱和）。</p></li></ol><h2 id="延伸实践" tabindex="-1">延伸实践 <a class="header-anchor" href="#延伸实践" aria-label="Permalink to &quot;延伸实践&quot;">​</a></h2><ul><li><a href="./../practice/PRACTICE-13-Sensorless-Control.html">路径13: 无位置传感器控制</a> — 无MATLAB许可证时，可用C仿真平台验证SMO/MRAS等无感算法</li><li><a href="./SIM-05-Digital-Twin.html">SIM-05: 数字孪生与真实电机模型</a> — 参数辨识、模型验证、在线自适应、仿真置信度评估</li></ul>',17))])}const A=r(_,[["render",i]]);export{O as __pageData,A as default};
